/****************************************************************************
 * LD2451 解析 + 端侧 policy（F · 王筠昊）
 *
 * 帧格式对齐 HLK 串口协议 V1.03：
 *   头 F4 F3 F2 F1 | 长度(LE,2B) | 体 | 尾 F8 F7 F6 F5
 * 体：目标数(1) + 报警(1) + N×(角/距/方向/速度/SNR 各 1B)
 *
 * 告警接口（改名须三人同意）：
 *   alert_level: NONE | SOFT | STRONG | EMERGENCY
 ****************************************************************************/

#ifndef EDGE_WALKER_LD2451_H
#define EDGE_WALKER_LD2451_H

#include "alert_output.h"

#include <stdbool.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

#define EW_LD2451_HDR0 0xF4
#define EW_LD2451_HDR1 0xF3
#define EW_LD2451_HDR2 0xF2
#define EW_LD2451_HDR3 0xF1
#define EW_LD2451_TAIL0 0xF8
#define EW_LD2451_TAIL1 0xF7
#define EW_LD2451_TAIL2 0xF6
#define EW_LD2451_TAIL3 0xF5

#define EW_LD2451_MAX_TARGETS 5

/* 台架初值（可后调） */
#ifndef EW_MIN_SPEED_KMH
#define EW_MIN_SPEED_KMH 5.0f
#endif
#ifndef EW_RANGE_SOFT_M
#define EW_RANGE_SOFT_M 25.0f
#endif
#ifndef EW_RANGE_STRONG_M
#define EW_RANGE_STRONG_M 15.0f
#endif
#ifndef EW_RANGE_EMERGENCY_M
#define EW_RANGE_EMERGENCY_M 8.0f
#endif
#ifndef EW_TTC_SOFT_S
#define EW_TTC_SOFT_S 5.0f
#endif
#ifndef EW_TTC_STRONG_S
#define EW_TTC_STRONG_S 3.0f
#endif
#ifndef EW_TTC_EMERGENCY_S
#define EW_TTC_EMERGENCY_S 1.5f
#endif

/*
 * 方向字节：官方表写 01=靠近 / 00=远离，但 V1.03 示例解析为
 * 00=靠近 / 01=远离。默认跟示例；台架若反了可 -DEW_DIR_APPROACH=0x01。
 */
#ifndef EW_DIR_APPROACH
#define EW_DIR_APPROACH 0x00
#endif
#ifndef EW_DIR_AWAY
#define EW_DIR_AWAY 0x01
#endif

typedef struct {
  float range_m;
  float speed_kmh;
  float azimuth_deg;
  float snr;
  float ttc_s; /* <0 表示无效 */
  bool approaching;
  bool valid;
} ew_track_t;

typedef struct {
  ew_alert_level_t level;
  float range_m;
  float speed_kmh;
  float azimuth_deg;
  float ttc_s;
  bool approaching;
  const char *reason;
} ew_decision_t;

/* 喂入原始字节流；凑齐一帧并选出有效目标则返回 true。 */
bool ew_ld2451_feed(const uint8_t *data, unsigned len, ew_track_t *out);

/* 重置帧状态机（换源 / 重连时调用）。 */
void ew_ld2451_reset(void);

/* 端侧门限：只靠近 + 最小速度 + 距离/TTC → 四级告警。不用 LLM。 */
ew_decision_t ew_decide(const ew_track_t *track);

/* 等级名，供日志 / 主机冒烟。 */
const char *ew_alert_level_name(ew_alert_level_t level);

#ifdef __cplusplus
}
#endif

#endif /* EDGE_WALKER_LD2451_H */

/****************************************************************************
 * LD2451 流式解析 + policy（F）
 ****************************************************************************/

#include "ew_ld2451.h"

#include <string.h>

enum {
  ST_HDR0 = 0,
  ST_HDR1,
  ST_HDR2,
  ST_HDR3,
  ST_LEN0,
  ST_LEN1,
  ST_BODY,
  ST_TAIL0,
  ST_TAIL1,
  ST_TAIL2,
  ST_TAIL3
};

#define EW_MAX_BODY 64

static int g_st = ST_HDR0;
static uint8_t g_body[EW_MAX_BODY];
static unsigned g_body_len;
static unsigned g_expect_body;
static uint8_t g_len_lo;

void ew_ld2451_reset(void)
{
  g_st = ST_HDR0;
  g_body_len = 0;
  g_expect_body = 0;
  g_len_lo = 0;
}

const char *ew_alert_level_name(ew_alert_level_t level)
{
  switch (level) {
    case EW_ALERT_SOFT:
      return "SOFT";
    case EW_ALERT_STRONG:
      return "STRONG";
    case EW_ALERT_EMERGENCY:
      return "EMERGENCY";
    case EW_ALERT_NONE:
    default:
      return "NONE";
  }
}

static bool decode_body(const uint8_t *body, unsigned len, ew_track_t *out)
{
  unsigned count;
  unsigned i;
  bool have = false;
  ew_track_t best;

  memset(out, 0, sizeof(*out));
  out->ttc_s = -1.0f;
  memset(&best, 0, sizeof(best));
  best.ttc_s = -1.0f;

  if (body == NULL || len < 2) {
    return false;
  }

  count = body[0];
  /* body[1] = alarm；判决以每目标方向为准，alarm 仅作参考 */
  (void)body[1];

  if (count > EW_LD2451_MAX_TARGETS) {
    count = EW_LD2451_MAX_TARGETS;
  }

  if (len < 2u + count * 5u) {
    return false;
  }

  for (i = 0; i < count; i++) {
    const uint8_t *t = &body[2 + i * 5];
    float range_m = (float)t[1];
    uint8_t dir = t[2];
    float speed_kmh = (float)t[3];
    bool approaching = (dir == (uint8_t)EW_DIR_APPROACH);
    float ttc = -1.0f;

    if (!approaching) {
      continue;
    }
    if (speed_kmh < EW_MIN_SPEED_KMH) {
      continue;
    }

    if (speed_kmh > 0.0f) {
      ttc = range_m / (speed_kmh / 3.6f);
    }

    if (!have || range_m < best.range_m) {
      best.valid = true;
      best.approaching = true;
      best.range_m = range_m;
      best.speed_kmh = speed_kmh;
      best.azimuth_deg = (float)((int)t[0] - 0x80);
      best.snr = (float)t[4];
      best.ttc_s = ttc;
      have = true;
    }
  }

  if (!have) {
    return false;
  }

  *out = best;
  return true;
}

bool ew_ld2451_feed(const uint8_t *data, unsigned len, ew_track_t *out)
{
  bool got = false;

  if (data == NULL || out == NULL) {
    return false;
  }

  for (unsigned i = 0; i < len; i++) {
    uint8_t b = data[i];

    switch (g_st) {
      case ST_HDR0:
        g_st = (b == EW_LD2451_HDR0) ? ST_HDR1 : ST_HDR0;
        break;
      case ST_HDR1:
        g_st = (b == EW_LD2451_HDR1) ? ST_HDR2 : ST_HDR0;
        break;
      case ST_HDR2:
        g_st = (b == EW_LD2451_HDR2) ? ST_HDR3 : ST_HDR0;
        break;
      case ST_HDR3:
        g_st = (b == EW_LD2451_HDR3) ? ST_LEN0 : ST_HDR0;
        break;
      case ST_LEN0:
        g_len_lo = b;
        g_st = ST_LEN1;
        break;
      case ST_LEN1:
        g_expect_body = (unsigned)g_len_lo | ((unsigned)b << 8);
        g_body_len = 0;
        if (g_expect_body > EW_MAX_BODY) {
          g_st = ST_HDR0;
        } else if (g_expect_body == 0) {
          g_st = ST_TAIL0;
        } else {
          g_st = ST_BODY;
        }
        break;
      case ST_BODY:
        g_body[g_body_len++] = b;
        if (g_body_len >= g_expect_body) {
          g_st = ST_TAIL0;
        }
        break;
      case ST_TAIL0:
        g_st = (b == EW_LD2451_TAIL0) ? ST_TAIL1 : ST_HDR0;
        break;
      case ST_TAIL1:
        g_st = (b == EW_LD2451_TAIL1) ? ST_TAIL2 : ST_HDR0;
        break;
      case ST_TAIL2:
        g_st = (b == EW_LD2451_TAIL2) ? ST_TAIL3 : ST_HDR0;
        break;
      case ST_TAIL3:
        if (b == EW_LD2451_TAIL3) {
          if (decode_body(g_body, g_body_len, out)) {
            got = true;
          }
        }
        g_st = ST_HDR0;
        break;
      default:
        g_st = ST_HDR0;
        break;
    }

    if (got) {
      /* 本包已产出一帧；余下字节下次再喂 */
      break;
    }
  }

  return got;
}

static ew_alert_level_t level_from_range_ttc(float range_m, float ttc_s)
{
  bool ttc_ok = (ttc_s >= 0.0f);

  if (range_m <= EW_RANGE_EMERGENCY_M ||
      (ttc_ok && ttc_s < EW_TTC_EMERGENCY_S)) {
    return EW_ALERT_EMERGENCY;
  }
  if (range_m <= EW_RANGE_STRONG_M ||
      (ttc_ok && ttc_s < EW_TTC_STRONG_S)) {
    return EW_ALERT_STRONG;
  }
  if (range_m <= EW_RANGE_SOFT_M ||
      (ttc_ok && ttc_s <= EW_TTC_SOFT_S)) {
    return EW_ALERT_SOFT;
  }
  return EW_ALERT_NONE;
}

ew_decision_t ew_decide(const ew_track_t *track)
{
  ew_decision_t d;

  memset(&d, 0, sizeof(d));
  d.level = EW_ALERT_NONE;
  d.ttc_s = -1.0f;
  d.reason = "idle";

  if (track == NULL || !track->valid) {
    d.reason = "invalid_track";
    return d;
  }

  d.range_m = track->range_m;
  d.speed_kmh = track->speed_kmh;
  d.azimuth_deg = track->azimuth_deg;
  d.ttc_s = track->ttc_s;
  d.approaching = track->approaching;

  if (!track->approaching) {
    d.reason = "not_approaching";
    return d;
  }
  if (track->speed_kmh < EW_MIN_SPEED_KMH) {
    d.reason = "below_min_speed";
    return d;
  }

  d.level = level_from_range_ttc(track->range_m, track->ttc_s);
  if (d.level == EW_ALERT_NONE) {
    d.reason = "out_of_threshold";
  } else if (d.level == EW_ALERT_EMERGENCY) {
    d.reason = "emergency_range_or_ttc";
  } else if (d.level == EW_ALERT_STRONG) {
    d.reason = "strong_range_or_ttc";
  } else {
    d.reason = "soft_range_or_ttc";
  }

  return d;
}

/****************************************************************************
 * 提醒出口（郑子轩主责；等级枚举与 F 冻结接口对齐）
 *
 * 全队冻结：alert_output(档位, 原因)
 * alert_level: NONE | SOFT | STRONG | EMERGENCY
 ****************************************************************************/

#ifndef EDGE_WALKER_ALERT_OUTPUT_H
#define EDGE_WALKER_ALERT_OUTPUT_H

#ifdef __cplusplus
extern "C" {
#endif

typedef enum {
  EW_ALERT_NONE = 0,
  EW_ALERT_SOFT = 1,
  EW_ALERT_STRONG = 2,
  EW_ALERT_EMERGENCY = 3
} ew_alert_level_t;

/* 兼容旧三档命名（逐步淘汰） */
#define EW_ALERT_WARN EW_ALERT_SOFT
#define EW_ALERT_CRIT EW_ALERT_EMERGENCY

/* 档位：0 静音 … 3 紧急。reason 可为 NULL。 */
void alert_output(ew_alert_level_t level, const char *reason);

#ifdef __cplusplus
}
#endif

#endif /* EDGE_WALKER_ALERT_OUTPUT_H */

/****************************************************************************
 * 提醒出口实现（郑子轩）
 *
 * 1) 控制台一定打印一行（NSH / 串口能看见）
 * 2) 板上若有 /dev/pwm0，则按档位开蜂鸣；没有则跳过，不算失败
 * 3) 可选刷新 LCD 色块（alert_lcd）
 ****************************************************************************/

#include "alert_output.h"
#include "alert_lcd.h"

#include <stdint.h>
#include <stdio.h>

#ifdef __NuttX__
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <errno.h>
#ifdef CONFIG_PWM
#include <nuttx/timers/pwm.h>
#endif
#endif

static const char *level_name(ew_alert_level_t level)
{
  switch (level) {
    case EW_ALERT_SOFT:
      return "SOFT";
    case EW_ALERT_STRONG:
      return "STRONG";
    case EW_ALERT_EMERGENCY:
      return "EMERGENCY";
    case EW_ALERT_NONE:
    default:
      return "NONE";
  }
}

#ifdef __NuttX__
#ifdef CONFIG_PWM
static void pwm_apply(ew_alert_level_t level)
{
  struct pwm_info_s info;
  int fd = open("/dev/pwm0", O_RDWR);
  if (fd < 0) {
    return;
  }

  if (level == EW_ALERT_NONE) {
    ioctl(fd, PWMIOC_STOP, 0);
    close(fd);
    return;
  }

  if (level == EW_ALERT_EMERGENCY) {
    info.frequency = 2800;
    info.duty = (uint32_t)(0.7f * 65536.0f);
  } else if (level == EW_ALERT_STRONG) {
    info.frequency = 2200;
    info.duty = (uint32_t)(0.5f * 65536.0f);
  } else {
    info.frequency = 1600;
    info.duty = (uint32_t)(0.3f * 65536.0f);
  }

#ifdef CONFIG_PWM_NCHANNELS
  info.channels[0].channel = 1;
  info.channels[0].duty = info.duty;
#endif

  if (ioctl(fd, PWMIOC_SETCHARACTERISTICS, (unsigned long)((uintptr_t)&info)) >= 0) {
    ioctl(fd, PWMIOC_START, 0);
  }
  close(fd);
}
#else
static void pwm_apply(ew_alert_level_t level)
{
  (void)level;
}
#endif
#endif

void alert_output(ew_alert_level_t level, const char *reason)
{
  printf("[alert_output] level=%s reason=%s\n",
         level_name(level),
         reason ? reason : "");
  fflush(stdout);

#ifdef __NuttX__
  pwm_apply(level);
#endif
  alert_lcd_show(level, reason);
}

