static void frame_one(uint8_t *out, unsigned *len,
                      uint8_t range_m, uint8_t dir, uint8_t speed)
{
  out[0] = 0xF4; out[1] = 0xF3; out[2] = 0xF2; out[3] = 0xF1;
  out[4] = 0x07; out[5] = 0x00;
  out[6] = 0x01;
