  ew_decision_t d;
  bool got;

  ew_ld2451_reset();
  memset(&t, 0, sizeof(t));
  got = ew_ld2451_feed(frame, len, &t);

  if (expect_track) {
    if (!got || !t.valid) {
      printf("FAIL %s: expected track\n", tag);
      return 1;
    }
