static void print_sniff_stats(const ew_sniff_stats_t *st)
{
  printf("[ew] sniff bytes=%lu hdr=%lu ok=%lu bad=%lu empty=%lu targets=%lu approach=%lu\n",
         (unsigned long)st->bytes_in,
         (unsigned long)st->headers,
         (unsigned long)st->frames_ok,
         (unsigned long)st->frames_bad,
         (unsigned long)st->frames_empty,
         (unsigned long)st->frames_targets,
         (unsigned long)st->approaching);
}

static void print_sniff_verdict(const ew_sniff_stats_t *st)
{
  if (st->bytes_in == 0) {
    printf("[ew] verdict: NO_UART_DATA — 检查 5V/共地/TX-RX/是否占用 ttyS1\n");
  } else if (st->headers == 0 && st->frames_ok == 0) {
    printf("[ew] verdict: BYTES_BUT_NO_FRAME — 有字节但无 F4F3F2F1 完整帧（波特率/接线交叉？）\n");
  } else if (st->frames_ok > 0 && st->approaching == 0) {
    printf("[ew] verdict: LINK_OK_NO_APPROACH — 链路正常，当前无靠近目标（空场正常）\n");
  } else if (st->approaching > 0) {
    printf("[ew] verdict: SEEING_APPROACH — 已看到靠近目标\n");
  } else {
    printf("[ew] verdict: PARTIAL — 有帧头但未收齐完整帧，再 sniff 久一点\n");
  }
}

static int cmd_sniff(int argc, char **argv)
{
  ew_sniff_stats_t st;
  int seconds = 10;

  memset(&st, 0, sizeof(st));
  if (argc >= 3) {
    seconds = atoi(argv[2]);
    if (seconds <= 0) {
      seconds = 10;
    }
    if (seconds > 120) {
      seconds = 120;
    }
  }

#ifdef __NuttX__
  {
    uint8_t buf[64];
    ew_track_t track;
    int fd;
    int elapsed_ms = 0;
    int tick_ms = 0;

    fd = open(EW_RADAR_DEV, O_RDONLY | O_NONBLOCK);
    if (fd < 0) {
      printf("[ew] open %s failed\n", EW_RADAR_DEV);
      return 1;
    }

    {
      struct termios tio;
      if (tcgetattr(fd, &tio) == 0) {
        cfsetispeed(&tio, B115200);
        cfsetospeed(&tio, B115200);
        tio.c_cflag = CS8 | CLOCAL | CREAD;
        tio.c_iflag = 0;
        tio.c_oflag = 0;
        tio.c_lflag = 0;
        tcsetattr(fd, TCSANOW, &tio);
      }
    }

    ew_ld2451_reset();
    printf("[ew] sniff %s @115200 for %ds (Ctrl-C to stop)\n",
           EW_RADAR_DEV, seconds);

    while (elapsed_ms < seconds * 1000) {
      int n = read(fd, buf, sizeof(buf));
      if (n > 0) {
        if (ew_ld2451_feed_sniff(buf, (unsigned)n, &st, &track) &&
            track.valid) {
          ew_decision_t d = ew_decide(&track);
          print_decision(&track, &d);
        }
      } else {
        usleep(20000);
        elapsed_ms += 20;
        tick_ms += 20;
      }

      if (tick_ms >= 1000) {
        print_sniff_stats(&st);
        tick_ms = 0;
      }
    }

    close(fd);
  }
#else
  /* 主机：喂官方示例 + 空帧，演示计数含义 */
  {
    static const uint8_t empty_frame[] = {
      0xF4, 0xF3, 0xF2, 0xF1, 0x02, 0x00, 0x00, 0x00,
      0xF8, 0xF7, 0xF6, 0xF5
    };
    static const uint8_t official[] = {
      0xF4, 0xF3, 0xF2, 0xF1, 0x11, 0x00, 0x03, 0x01,
      0x8A, 0x28, 0x00, 0x3C, 0x15, 0x8A, 0x1E, 0x01, 0x3C, 0x0F,
      0x76, 0x5F, 0x00, 0x3C, 0x0F, 0xF8, 0xF7, 0xF6, 0xF5
    };
    ew_track_t track;

    (void)seconds;
    ew_ld2451_reset();
    printf("[ew] sniff host demo (empty + official example)\n");
    ew_ld2451_feed_sniff(empty_frame, sizeof(empty_frame), &st, &track);
    ew_ld2451_feed_sniff(official, sizeof(official), &st, &track);
  }
#endif

  print_sniff_stats(&st);
  print_sniff_verdict(&st);
  return 0;
}

